//! Schemas of the skeletal rig tools: `rig_create`, `rig_pose`, `clip_apply`.
use super::ToolSchema;

pub(crate) const RIG_TOOLS: &[ToolSchema] = &[
    ToolSchema {
        name: "rig_create",
        description: "Define (replace) the document's skeletal rig over existing <g> group ids, in ONE undoable edit. bones: 1-128 of {id, pivot?, parent?}: id is the group the bone moves (letters, digits, _ and - only, so rename other ids first), pivot is [x,y] in the group's own coordinate space or \"center\" (default: the centre of the group's bounds, taken now), parent is another bone id whose group must contain this bone's group (children then follow the parent through the group tree; only local values are keyed). Bone cycles, unknown or duplicate ids, non-finite pivots and non-group elements are rejected. roles: optional {head, torso, arm_l, arm_r, leg_l, leg_r, tail} mapping a role to a bone id, used by clip_apply. The rig is stored in the document (a <desc id=\"vexel-rig\"> element), so it saves, reopens and undoes with the file. Example: {\"bones\":[{\"id\":\"body\"},{\"id\":\"arm\",\"pivot\":[120,80],\"parent\":\"body\"}],\"roles\":{\"torso\":\"body\",\"arm_r\":\"arm\"}}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"bones\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":128,\"items\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":120},\"pivot\":{\"type\":[\"array\",\"string\"]},\"parent\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":120}},\"required\":[\"id\"],\"additionalProperties\":false}},\"roles\":{\"type\":\"object\"}}",
        required: "documentId,bones",
        fields: "documentId:string;bones:array;roles:object",
    },
    ToolSchema {
        name: "rig_pose",
        description: "Key bone poses of the rig made by rig_create in ONE atomic, undoable edit. poses: 1-256 of {tick, bones: {boneId: {rotate?, translate?, scale?}}, ease?}; rotate is degrees about the bone's pivot, translate is [x,y], scale is a number or [x,y]. Each key is the bone's full local pose (omitted parts are rest: rotate 0, translate 0, scale 1) and writes the group's trs transform track rig_<boneId> (created on first use, extended or overwritten at the same tick later). ease shapes the segment after the key (same names, bezier:x1,y1,x2,y2 or [x1,y1,x2,y2] as native_timeline_set_property_key). interpolation: step|linear|cubic for new tracks (default linear). noise: {amplitude, frequency?, seed?, octaves?} adds seeded smooth noise to bones whose track is created by this call. At most 16384 keys; every tick must be below the timeline duration. Example: {\"poses\":[{\"tick\":0,\"bones\":{\"arm\":{\"rotate\":0}}},{\"tick\":12,\"bones\":{\"arm\":{\"rotate\":60}},\"ease\":\"ease_in_out\"}]}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"poses\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"items\":{\"type\":\"object\",\"properties\":{\"tick\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"bones\":{\"type\":\"object\"},\"ease\":{\"type\":[\"string\",\"array\"]}},\"required\":[\"tick\",\"bones\"],\"additionalProperties\":false}},\"interpolation\":{\"type\":\"string\",\"enum\":[\"step\",\"linear\",\"cubic\"]},\"noise\":{\"type\":\"object\"}}",
        required: "documentId,poses",
        fields: "documentId:string;poses:array;interpolation:string;noise:object",
    },
    ToolSchema {
        name: "clip_apply",
        description: "Apply a built-in procedural motion clip to the rig's bones by role, in ONE atomic, undoable edit (same writer as rig_pose). clip: walk, run, idle, talk_body, blink_bob (alias blink-body-bob), wave, jump. Needs these roles in rig_create: walk/run leg_l and leg_r (arm_l, arm_r, torso, head, tail are used when present); idle and jump torso (plus arms, legs, head, tail when present); talk_body and blink_bob head (plus torso, arms); wave arm_r (plus head, torso). Parameters: start (tick, default 0), duration (ticks, required, 1-1000000), loops (cycles over the duration, 1-64, default 1), speed (multiplies loops; cycles = round(loops*speed), 0.25-4, default 1), amplitude (0-4, default 1), mode loop|pingpong (loop: last key equals first key; pingpong: each cycle plays forward then back), ease (applied to every key). Deterministic: the same arguments always write the same keys. Keys overwrite earlier keys at the same ticks of the same bone tracks, so clips can be chained. Every tick must be below the timeline duration. Example: {\"clip\":\"walk\",\"start\":0,\"duration\":48,\"loops\":2}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"clip\":{\"type\":\"string\",\"enum\":[\"walk\",\"run\",\"idle\",\"talk_body\",\"blink_bob\",\"blink-body-bob\",\"wave\",\"jump\"]},\"start\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"duration\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000000},\"loops\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64},\"speed\":{\"type\":\"number\",\"minimum\":0.25,\"maximum\":4},\"amplitude\":{\"type\":\"number\",\"minimum\":0,\"maximum\":4},\"mode\":{\"type\":\"string\",\"enum\":[\"loop\",\"pingpong\"]},\"ease\":{\"type\":[\"string\",\"array\"]}}",
        required: "documentId,clip,duration",
        fields: "documentId:string;clip:string;start:integer;duration:integer;loops:integer;speed:number;amplitude:number;mode:string;ease:string|array",
    },
];
